CREATE TABLE "Player" ("id" TEXT NOT NULL PRIMARY KEY, "name" TEXT NOT NULL);
CREATE TABLE "Village" ("id" TEXT NOT NULL PRIMARY KEY, "playerId" TEXT NOT NULL, "name" TEXT NOT NULL, "x" INTEGER NOT NULL DEFAULT 482, "y" INTEGER NOT NULL DEFAULT 517, "state" TEXT NOT NULL, "updatedAt" DATETIME NOT NULL, "version" INTEGER NOT NULL DEFAULT 0, CONSTRAINT "Village_playerId_fkey" FOREIGN KEY ("playerId") REFERENCES "Player" ("id") ON DELETE RESTRICT ON UPDATE CASCADE);
